---@alias gcp.androidmanagement_v1.DefaultApplicationSettingAttemptAttemptOutcomeEnum "ATTEMPT_OUTCOME_UNSPECIFIED"|"SUCCESS"|"APP_NOT_INSTALLED"|"APP_SIGNING_CERT_MISMATCH"|"OTHER_FAILURE"

---@alias gcp.androidmanagement_v1.DefaultApplicationSettingAttemptList gcp.androidmanagement_v1.DefaultApplicationSettingAttempt[]

---@alias gcp.androidmanagement_v1.DefaultApplicationSettingDefaultApplicationScopesItemEnum "DEFAULT_APPLICATION_SCOPE_UNSPECIFIED"|"SCOPE_FULLY_MANAGED"|"SCOPE_WORK_PROFILE"|"SCOPE_PERSONAL_PROFILE"

---@alias gcp.androidmanagement_v1.DefaultApplicationSettingDefaultApplicationScopesItemEnumList (gcp.androidmanagement_v1.DefaultApplicationSettingDefaultApplicationScopesItemEnum|string)[]

---@alias gcp.androidmanagement_v1.DefaultApplicationSettingDefaultApplicationTypeEnum "DEFAULT_APPLICATION_TYPE_UNSPECIFIED"|"DEFAULT_ASSISTANT"|"DEFAULT_BROWSER"|"DEFAULT_CALL_REDIRECTION"|"DEFAULT_CALL_SCREENING"|"DEFAULT_DIALER"|"DEFAULT_HOME"|"DEFAULT_SMS"|"DEFAULT_WALLET"

---@alias gcp.androidmanagement_v1.DefaultApplicationSettingList gcp.androidmanagement_v1.DefaultApplicationSetting[]

