---@alias gcp.androidmanagement_v1.EsimCommandStatusStatusEnum "STATUS_UNSPECIFIED"|"SUCCESS"|"IN_PROGRESS"|"PENDING_USER_ACTION"|"ERROR_SETUP_IN_PROGRESS"|"ERROR_USER_DENIED"|"INTERNAL_ERROR"|"ERROR_ICC_ID_NOT_FOUND"|"ERROR_MULTIPLE_ACTIVE_ESIMS_NO_AVAILABLE_SLOT"

