---@alias gcp.androidmanagement_v1.NonComplianceDetailInstallationFailureReasonEnum "INSTALLATION_FAILURE_REASON_UNSPECIFIED"|"INSTALLATION_FAILURE_REASON_UNKNOWN"|"IN_PROGRESS"|"NOT_FOUND"|"NOT_COMPATIBLE_WITH_DEVICE"|"NOT_APPROVED"|"PERMISSIONS_NOT_ACCEPTED"|"NOT_AVAILABLE_IN_COUNTRY"|"NO_LICENSES_REMAINING"|"NOT_ENROLLED"|"USER_INVALID"|"NETWORK_ERROR_UNRELIABLE_CONNECTION"|"INSUFFICIENT_STORAGE"

---@alias gcp.androidmanagement_v1.NonComplianceDetailList gcp.androidmanagement_v1.NonComplianceDetail[]

---@alias gcp.androidmanagement_v1.NonComplianceDetailNonComplianceReasonEnum "NON_COMPLIANCE_REASON_UNSPECIFIED"|"API_LEVEL"|"MANAGEMENT_MODE"|"USER_ACTION"|"INVALID_VALUE"|"APP_NOT_INSTALLED"|"UNSUPPORTED"|"APP_INSTALLED"|"PENDING"|"APP_INCOMPATIBLE"|"APP_NOT_UPDATED"|"OS_NOT_PERMITTED"|"DEVICE_INCOMPATIBLE"|"APP_SIGNING_CERT_MISMATCH"|"PROJECT_NOT_PERMITTED"

