---Requirements for the password used to unlock a device.
---@class gcp.androidmanagement_v1.PasswordRequirements
---@field passwordMinimumNonLetter? number Optional. Minimum number of non-letter characters (numerical digits or symbols) required in the password. Only enforced when password_quality is COMPLEX.
---@field passwordQuality? gcp.androidmanagement_v1.PasswordRequirementsPasswordQualityEnum|string Optional. The required password quality.
---@field passwordMinimumLength? number Optional. The minimum allowed password length. A value of 0 means there is no restriction. Only enforced when password_quality is NUMERIC, NUMERIC_COMPLEX, ALPHABETIC, ALPHANUMERIC, or COMPLEX.
---@field unifiedLockSettings? gcp.androidmanagement_v1.PasswordRequirementsUnifiedLockSettingsEnum|string Optional. Controls whether a unified lock is allowed for the device and the work profile, on devices running Android 9 and above with a work profile. This can be set only if password_scope is set to SCOPE_PROFILE, the policy will be rejected otherwise. If user has not set a separate work lock and this field is set to REQUIRE_SEPARATE_WORK_LOCK, a NonComplianceDetail is reported with nonComplianceReason set to USER_ACTION.
---@field passwordMinimumUpperCase? number Optional. Minimum number of upper case letters required in the password. Only enforced when password_quality is COMPLEX.
---@field passwordHistoryLength? number Optional. The length of the password history. After setting this field, the user won't be able to enter a new password that is the same as any password in the history. A value of 0 means there is no restriction.
---@field passwordMinimumLowerCase? number Optional. Minimum number of lower case letters required in the password. Only enforced when password_quality is COMPLEX.
---@field passwordMinimumLetters? number Optional. Minimum number of letters required in the password. Only enforced when password_quality is COMPLEX.
---@field passwordMinimumNumeric? number Optional. Minimum number of numerical digits required in the password. Only enforced when password_quality is COMPLEX.
---@field passwordScope? gcp.androidmanagement_v1.PasswordRequirementsPasswordScopeEnum|string Optional. The scope that the password requirement applies to.
---@field passwordMinimumSymbols? number Optional. Minimum number of symbols required in the password. Only enforced when password_quality is COMPLEX.
---@field requirePasswordUnlock? gcp.androidmanagement_v1.PasswordRequirementsRequirePasswordUnlockEnum|string Optional. The length of time after a device or work profile is unlocked using a strong form of authentication (password, PIN, pattern) that it can be unlocked using any other authentication method (e.g. fingerprint, trust agents, face). After the specified time period elapses, only strong forms of authentication can be used to unlock the device or work profile.
---@field maximumFailedPasswordsForWipe? number Optional. Number of incorrect device-unlock passwords that can be entered before a device is wiped. A value of 0 means there is no restriction.
---@field passwordExpirationTimeout? string Optional. Password expiration timeout.

---@alias gcp.androidmanagement_v1.PasswordRequirementsList gcp.androidmanagement_v1.PasswordRequirements[]

---@alias gcp.androidmanagement_v1.PasswordRequirementsPasswordQualityEnum "PASSWORD_QUALITY_UNSPECIFIED"|"BIOMETRIC_WEAK"|"SOMETHING"|"NUMERIC"|"NUMERIC_COMPLEX"|"ALPHABETIC"|"ALPHANUMERIC"|"COMPLEX"|"COMPLEXITY_LOW"|"COMPLEXITY_MEDIUM"|"COMPLEXITY_HIGH"

---@alias gcp.androidmanagement_v1.PasswordRequirementsPasswordScopeEnum "SCOPE_UNSPECIFIED"|"SCOPE_DEVICE"|"SCOPE_PROFILE"

---@alias gcp.androidmanagement_v1.PasswordRequirementsRequirePasswordUnlockEnum "REQUIRE_PASSWORD_UNLOCK_UNSPECIFIED"|"USE_DEFAULT_DEVICE_TIMEOUT"|"REQUIRE_EVERY_DAY"

---@alias gcp.androidmanagement_v1.PasswordRequirementsUnifiedLockSettingsEnum "UNIFIED_LOCK_SETTINGS_UNSPECIFIED"|"ALLOW_UNIFIED_WORK_AND_PERSONAL_LOCK"|"REQUIRE_SEPARATE_WORK_LOCK"

---@class gcp.androidmanagement_v1.PatchEnterprisesDevicesRequest
---@field softwareInfo? gcp.androidmanagement_v1.SoftwareInfo Detailed information about the device software. This information is only available if softwareInfoEnabled is true in the device's policy.
---@field enrollmentTime? string The time of device enrollment.
---@field networkInfo? gcp.androidmanagement_v1.NetworkInfo Device network information. This information is only available if networkInfoEnabled is true in the device's policy.
---@field lastPolicyComplianceReportTime? string Deprecated.
---@field appliedPasswordPolicies? gcp.androidmanagement_v1.PasswordRequirementsList The password requirements currently applied to the device. This field exists because the applied requirements may be slightly different from those specified in passwordPolicies in some cases. Note that this field does not provide information about password compliance. For non-compliance information, see nonComplianceDetails. NonComplianceDetail.fieldPath, is set based on passwordPolicies, not based on this field.
---@field enrollmentTokenName? string If the device was enrolled with an enrollment token, this field contains the name of the token.
---@field hardwareStatusSamples? gcp.androidmanagement_v1.HardwareStatusList Hardware status samples in chronological order. This information is only available if hardwareStatusEnabled is true in the device's policy.
---@field user? gcp.androidmanagement_v1.User The user who owns the device.
---@field applicationReports? gcp.androidmanagement_v1.ApplicationReportList Reports for apps installed on the device. This information is only available when application_reports_enabled is true in the device's policy.
---@field defaultApplicationInfo? gcp.androidmanagement_v1.DefaultApplicationInfoList Output only. The default application information for the DefaultApplicationType. This information is only available if defaultApplicationInfoReportingEnabled is true in the device's policy. Available on Android 16 and above.All app types are reported on fully managed devices. DEFAULT_BROWSER, DEFAULT_CALL_REDIRECTION, DEFAULT_CALL_SCREENING and DEFAULT_DIALER types are reported for the work profiles on company-owned devices with a work profile and personally-owned devices. DEFAULT_WALLET is also reported for company-owned devices with a work profile, but will only include work profile information.
---@field enrollmentTokenData? string If the device was enrolled with an enrollment token with additional data provided, this field contains that data.
---@field ownership? gcp.androidmanagement_v1.DeviceOwnershipEnum|string Ownership of the managed device.
---@field lastPolicySyncTime? string The last time the device fetched its policy.
---@field appliedPolicyVersion? string The version of the policy currently applied to the device.
---@field memoryEvents? gcp.androidmanagement_v1.MemoryEventList Events related to memory and storage measurements in chronological order. This information is only available if memoryInfoEnabled is true in the device's policy.Events are retained for a certain period of time and old events are deleted.
---@field lastStatusReportTime? string The last time the device sent a status report.
---@field powerManagementEvents? gcp.androidmanagement_v1.PowerManagementEventList Power management events on the device in chronological order. This information is only available if powerManagementEventsEnabled is true in the device's policy.
---@field dpcMigrationInfo? gcp.androidmanagement_v1.DpcMigrationInfo Output only. Information related to whether this device was migrated from being managed by another Device Policy Controller (DPC).
---@field disabledReason? gcp.androidmanagement_v1.UserFacingMessage If the device state is DISABLED, an optional message that is displayed on the device indicating the reason the device is disabled. This field can be modified by a patch request.
---@field apiLevel? number The API level of the Android platform version running on the device.
---@field policyCompliant? boolean Whether the device is compliant with its policy.
---@field systemProperties? gcp.androidmanagement_v1.StringMap Map of selected system properties name and value related to the device. This information is only available if systemPropertiesEnabled is true in the device's policy.
---@field commonCriteriaModeInfo? gcp.androidmanagement_v1.CommonCriteriaModeInfo Information about Common Criteria Mode—security standards defined in the Common Criteria for Information Technology Security Evaluation (https://www.commoncriteriaportal.org/) (CC).This information is only available if statusReportingSettings.commonCriteriaModeEnabled is true in the device's policy the device is company-owned.
---@field appliedPolicyName? string The name of the policy currently applied to the device.
---@field nonComplianceDetails? gcp.androidmanagement_v1.NonComplianceDetailList Details about policy settings that the device is not compliant with.
---@field previousDeviceNames? gcp.androidmanagement_v1.StringList If the same physical device has been enrolled multiple times, this field contains its previous device names. The serial number is used as the unique identifier to determine if the same physical device has enrolled previously. The names are in chronological order.
---@field memoryInfo? gcp.androidmanagement_v1.MemoryInfo Memory information: contains information about device memory and storage.
---@field displays? gcp.androidmanagement_v1.DisplayList Detailed information about displays on the device. This information is only available if displayInfoEnabled is true in the device's policy.
---@field deviceSettings? gcp.androidmanagement_v1.DeviceSettings Device settings information. This information is only available if deviceSettingsEnabled is true in the device's policy.
---@field state? gcp.androidmanagement_v1.DeviceStateEnum|string The state to be applied to the device. This field can be modified by a patch request. Note that when calling enterprises.devices.patch, ACTIVE and DISABLED are the only allowable values. To enter the device into a DELETED state, call enterprises.devices.delete.
---@field appliedState? gcp.androidmanagement_v1.DeviceAppliedStateEnum|string The state currently applied to the device.
---@field userName? string The resource name of the user that owns this device in the form enterprises/{enterpriseId}/users/{userId}.
---@field hardwareInfo? gcp.androidmanagement_v1.HardwareInfo Detailed information about the device hardware.
---@field managementMode? gcp.androidmanagement_v1.DeviceManagementModeEnum|string The type of management mode Android Device Policy takes on the device. This influences which policy settings are supported.
---@field securityPosture? gcp.androidmanagement_v1.SecurityPosture Device's security posture value that reflects how secure the device is.
---@field policyName? string The name of the policy applied to the device, in the form enterprises/{enterpriseId}/policies/{policyId}. If not specified, the policy_name for the device's user is applied. This field can be modified by a patch request. You can specify only the policyId when calling enterprises.devices.patch, as long as the policyId doesn’t contain any slashes. The rest of the policy name is inferred.
---@field name string The name of the device in the form enterprises/{enterpriseId}/devices/{deviceId}.
---@field updateMask? string The field mask indicating the fields to update. If not set, all modifiable fields will be modified.

---@class gcp.androidmanagement_v1.PatchEnterprisesPoliciesRequest
---@field statusBarDisabled? boolean Whether the status bar is disabled. This disables notifications, quick settings, and other screen overlays that allow escape from full-screen mode. DEPRECATED. To disable the status bar on a kiosk device, use InstallType KIOSK or kioskCustomLauncherEnabled.
---@field personalUsagePolicies? gcp.androidmanagement_v1.PersonalUsagePolicies Policies managing personal usage on a company-owned device.
---@field passwordPolicies? gcp.androidmanagement_v1.PasswordRequirementsList Optional. Password requirement policies. Different policies can be set for work profile or fully managed devices by setting the password_scope field in the policy.
---@field smsDisabled? boolean Whether sending and receiving SMS messages is disabled.
---@field backupService? gcp.androidmanagement_v1.PolicyBackupServiceEnum|string Optional. Controls whether the backup service is disabled. Supported only on fully managed devices running Android 8 and above.
---@field cameraAccess? gcp.androidmanagement_v1.PolicyCameraAccessEnum|string Controls the use of the camera and whether the user has access to the camera access toggle.
---@field deviceWidePolicies? gcp.androidmanagement_v1.DeviceWidePolicies Optional. Policies controlling the device on company-owned devices.
---@field statusReportingSettings? gcp.androidmanagement_v1.StatusReportingSettings Status reporting settings
---@field addUserDisabled? boolean Whether adding new users and profiles is disabled. For devices where managementMode is DEVICE_OWNER this field is ignored and the user is never allowed to add or remove users.
---@field encryptionPolicy? gcp.androidmanagement_v1.PolicyEncryptionPolicyEnum|string Whether encryption is enabled
---@field policyEnforcementRules? gcp.androidmanagement_v1.PolicyEnforcementRuleList Rules that define the behavior when a particular policy can not be applied on device
---@field appFunctions? gcp.androidmanagement_v1.PolicyAppFunctionsEnum|string Optional. Controls whether apps on the device for fully managed devices or in the work profile for devices with work profiles are allowed to expose app functions.
---@field locationMode? gcp.androidmanagement_v1.PolicyLocationModeEnum|string The degree of location detection enabled.
---@field defaultPermissionPolicy? gcp.androidmanagement_v1.PolicyDefaultPermissionPolicyEnum|string The default permission policy for runtime permission requests.
---@field androidDevicePolicyTracks? gcp.androidmanagement_v1.PolicyAndroidDevicePolicyTracksItemEnumList This setting is not supported. Any value is ignored.
---@field unmuteMicrophoneDisabled? boolean If microphone_access is set to any value other than MICROPHONE_ACCESS_UNSPECIFIED, this has no effect. Otherwise this field controls whether microphones are disabled: If true, all microphones are disabled, otherwise they are available. This is available only on fully managed devices.
---@field microphoneAccess? gcp.androidmanagement_v1.PolicyMicrophoneAccessEnum|string Controls the use of the microphone and whether the user has access to the microphone access toggle. This applies only on fully managed devices.
---@field installUnknownSourcesAllowed? boolean This field has no effect.
---@field kioskCustomLauncherEnabled? boolean Whether the kiosk custom launcher is enabled. This replaces the home screen with a launcher that locks down the device to the apps installed via the applications setting. Apps appear on a single page in alphabetical order. Use kioskCustomization to further configure the kiosk device behavior.
---@field usbMassStorageEnabled? boolean Whether USB storage is enabled. Deprecated.
---@field deviceRadioState? gcp.androidmanagement_v1.DeviceRadioState Optional. Covers controls for radio state such as Wi-Fi, bluetooth, and more.
---@field networkResetDisabled? boolean Whether resetting network settings is disabled. This applies only on fully managed devices. A NonComplianceDetail with MANAGEMENT_MODE is reported for other management modes.
---@field wipeDataFlags? gcp.androidmanagement_v1.PolicyWipeDataFlagsItemEnumList Optional. Wipe flags to indicate what data is wiped when a device or profile wipe is triggered due to any reason (for example, non-compliance). This does not apply to the enterprises.devices.delete method. . This list must not have duplicates.
---@field defaultApplicationSettings? gcp.androidmanagement_v1.DefaultApplicationSettingList Optional. The default application setting for supported types. If the default application is successfully set for at least one app type on a profile, users are prevented from changing any default applications on that profile.Only one DefaultApplicationSetting is allowed for each DefaultApplicationType.Warning: Do not configure this and persistent_preferred_activities for the same intent domain, such as web browsing. Setting both for the same intent domain can lead to unpredictable behavior.See Default application settings (https://developers.google.com/android/management/default-application-settings) guide for more details.
---@field factoryResetDisabled? boolean Whether factory resetting from settings is disabled.
---@field privateKeySelectionEnabled? boolean Allows showing UI on a device for a user to choose a private key alias if there are no matching rules in ChoosePrivateKeyRules. For devices below Android P, setting this may leave enterprise keys vulnerable. This value will have no effect if any application has CERT_SELECTION delegation scope.
---@field dataRoamingDisabled? boolean Whether roaming data services are disabled.
---@field wifiConfigsLockdownEnabled? boolean This is deprecated.
---@field longSupportMessage? gcp.androidmanagement_v1.UserFacingMessage A message displayed to the user in the device administators settings screen.
---@field bluetoothContactSharingDisabled? boolean Whether bluetooth contact sharing is disabled.
---@field debuggingFeaturesAllowed? boolean Whether the user is allowed to enable debugging features.
---@field adjustVolumeDisabled? boolean Whether adjusting the master volume is disabled. Also mutes the device. The setting has effect only on fully managed devices.
---@field autofillPolicy? gcp.androidmanagement_v1.PolicyAutofillPolicyEnum|string Optional. The policy for the autofill service.
---@field mobileNetworksConfigDisabled? boolean Whether configuring mobile networks is disabled.
---@field assistContentPolicy? gcp.androidmanagement_v1.PolicyAssistContentPolicyEnum|string Optional. Controls whether AssistContent (https://developer.android.com/reference/android/app/assist/AssistContent) is allowed to be sent to a privileged app such as an assistant app. AssistContent includes screenshots and information about an app, such as package name. This is supported on Android 15 and above.
---@field autoTimeRequired? boolean Whether auto time is required, which prevents the user from manually setting the date and time. If autoDateAndTimeZone is set, this field is ignored.
---@field applications? gcp.androidmanagement_v1.ApplicationPolicyList Policy applied to apps. This can have at most 3,000 elements.
---@field setupActions? gcp.androidmanagement_v1.SetupActionList Action to take during the setup process. At most one action may be specified.
---@field autoDateAndTimeZone? gcp.androidmanagement_v1.PolicyAutoDateAndTimeZoneEnum|string Whether auto date, time, and time zone are enabled on a company-owned device. If this is set, then autoTimeRequired is ignored.
---@field alwaysOnVpnPackage? gcp.androidmanagement_v1.AlwaysOnVpnPackage Configuration for an always-on VPN connection. Use with vpn_config_disabled to prevent modification of this setting.
---@field skipFirstUseHintsEnabled? boolean Flag to skip hints on the first use. Enterprise admin can enable the system recommendation for apps to skip their user tutorial and other introductory hints on first start-up.
---@field usageLog? gcp.androidmanagement_v1.UsageLog Optional. Configuration of device activity logging.
---@field version? string The version of the policy. This is a read-only field. The version is incremented each time the policy is updated.
---@field maximumTimeToLock? string Maximum time in milliseconds for user activity until the device locks. A value of 0 means there is no restriction.
---@field safeBootDisabled? boolean Whether rebooting the device into safe boot is disabled.
---@field credentialsConfigDisabled? boolean Whether configuring user credentials is disabled.
---@field tetheringConfigDisabled? boolean Whether configuring tethering and portable hotspots is disabled. If tetheringSettings is set to anything other than TETHERING_SETTINGS_UNSPECIFIED, this setting is ignored.
---@field oncCertificateProviders? gcp.androidmanagement_v1.OncCertificateProviderList This feature is not generally available.
---@field vpnConfigDisabled? boolean Whether configuring VPN is disabled.
---@field setWallpaperDisabled? boolean Whether changing the wallpaper is disabled.
---@field deviceOwnerLockScreenInfo? gcp.androidmanagement_v1.UserFacingMessage Optional. The device owner information to be shown on the lock screen.
---@field passwordRequirements? gcp.androidmanagement_v1.PasswordRequirements Password requirements. The field password_requirements.require_password_unlock must not be set. DEPRECATED - Use passwordPolicies.Note:Complexity-based values of PasswordQuality, that is, COMPLEXITY_LOW, COMPLEXITY_MEDIUM, and COMPLEXITY_HIGH, cannot be used here. unified_lock_settings cannot be used here.
---@field crossProfilePolicies? gcp.androidmanagement_v1.CrossProfilePolicies Optional. Cross-profile policies applied on the device.
---@field workAccountSetupConfig? gcp.androidmanagement_v1.WorkAccountSetupConfig Optional. Controls the work account setup configuration, such as details of whether a Google authenticated account is required.
---@field accountTypesWithManagementDisabled? gcp.androidmanagement_v1.StringList Account types that can't be managed by the user.
---@field kioskCustomization? gcp.androidmanagement_v1.KioskCustomization Optional. Settings controlling the behavior of a device in kiosk mode. To enable kiosk mode, set kioskCustomLauncherEnabled to true or specify an app in the policy with the KIOSK role.
---@field preferentialNetworkService? gcp.androidmanagement_v1.PolicyPreferentialNetworkServiceEnum|string Controls whether preferential network service is enabled on the work profile or on fully managed devices. For example, an organization may have an agreement with a carrier that all of the work data from its employees' devices will be sent via a network service dedicated for enterprise use. An example of a supported preferential network service is the enterprise slice on 5G networks. This policy has no effect if preferentialNetworkServiceSettings or ApplicationPolicy.preferentialNetworkId is set on devices running Android 13 or above.
---@field setUserIconDisabled? boolean Whether changing the user icon is disabled. This applies only on devices running Android 7 and above.
---@field stayOnPluggedModes? gcp.androidmanagement_v1.PolicyStayOnPluggedModesItemEnumList The battery plugged in modes for which the device stays on. When using this setting, it is recommended to clear maximum_time_to_lock so that the device doesn't lock itself while it stays on.
---@field bluetoothConfigDisabled? boolean Whether configuring bluetooth is disabled.
---@field displaySettings? gcp.androidmanagement_v1.DisplaySettings Optional. Controls for the display settings.
---@field screenCaptureDisabled? boolean Whether screen capture is disabled. This also blocks Circle to Search (https://support.google.com/android/answer/14508957).
---@field choosePrivateKeyRules? gcp.androidmanagement_v1.ChoosePrivateKeyRuleList Rules for determining apps' access to private keys. See ChoosePrivateKeyRule for details. This must be empty if any application has CERT_SELECTION delegation scope.
---@field removeUserDisabled? boolean Whether removing other users is disabled.
---@field appAutoUpdatePolicy? gcp.androidmanagement_v1.PolicyAppAutoUpdatePolicyEnum|string Recommended alternative: autoUpdateMode which is set per app, provides greater flexibility around update frequency.When autoUpdateMode is set to AUTO_UPDATE_POSTPONED or AUTO_UPDATE_HIGH_PRIORITY, this field has no effect.The app auto update policy, which controls when automatic app updates can be applied.
---@field shortSupportMessage? gcp.androidmanagement_v1.UserFacingMessage A message displayed to the user in the settings screen wherever functionality has been disabled by the admin. If the message is longer than 200 characters it may be truncated.
---@field cellBroadcastsConfigDisabled? boolean Whether configuring cell broadcast is disabled.
---@field enterpriseDisplayNameVisibility? gcp.androidmanagement_v1.PolicyEnterpriseDisplayNameVisibilityEnum|string Optional. Controls whether the enterpriseDisplayName is visible on the device (e.g. lock screen message on company-owned devices).
---@field uninstallAppsDisabled? boolean Whether user uninstallation of applications is disabled. This prevents apps from being uninstalled, even those removed using applications
---@field bluetoothDisabled? boolean Whether bluetooth is disabled. Prefer this setting over bluetooth_config_disabled because bluetooth_config_disabled can be bypassed by the user.
---@field playStoreMode? gcp.androidmanagement_v1.PolicyPlayStoreModeEnum|string This mode controls which apps are available to the user in the Play Store and the behavior on the device when apps are removed from the policy.
---@field credentialProviderPolicyDefault? gcp.androidmanagement_v1.PolicyCredentialProviderPolicyDefaultEnum|string Optional. Controls which apps are allowed to act as credential providers on Android 14 and above. These apps store credentials, see this (https://developer.android.com/training/sign-in/passkeys) and this (https://developer.android.com/reference/androidx/credentials/CredentialManager) for details. See also credentialProviderPolicy.
---@field outgoingBeamDisabled? boolean Whether using NFC to beam data from apps is disabled.
---@field wifiConfigDisabled? boolean Whether configuring Wi-Fi networks is disabled. Supported on fully managed devices and work profiles on company-owned devices. For fully managed devices, setting this to true removes all configured networks and retains only the networks configured using openNetworkConfiguration. For work profiles on company-owned devices, existing configured networks are not affected and the user is not allowed to add, remove, or modify Wi-Fi networks. If configureWifi is set to anything other than CONFIGURE_WIFI_UNSPECIFIED, this setting is ignored. Note: If a network connection can't be made at boot time and configuring Wi-Fi is disabled then network escape hatch will be shown in order to refresh the device policy (see networkEscapeHatchEnabled).
---@field keyguardDisabledFeatures? gcp.androidmanagement_v1.PolicyKeyguardDisabledFeaturesItemEnumList Disabled keyguard customizations, such as widgets.
---@field persistentPreferredActivities? gcp.androidmanagement_v1.PersistentPreferredActivityList Default intent handler activities.Warning: Do not configure this and default_application_settings for the same intent domain, such as web browsing. Setting both for the same intent domain can lead to unpredictable behavior.
---@field frpAdminEmails? gcp.androidmanagement_v1.StringList Email addresses of device administrators for factory reset protection. When the device is factory reset, it will require one of these admins to log in with the Google account email and password to unlock the device. If no admins are specified, the device won't provide factory reset protection.
---@field cameraDisabled? boolean If camera_access is set to any value other than CAMERA_ACCESS_UNSPECIFIED, this has no effect. Otherwise this field controls whether cameras are disabled: If true, all cameras are disabled, otherwise they are available. For fully managed devices this field applies for all apps on the device. For work profiles, this field applies only to apps in the work profile, and the camera access of apps outside the work profile is unaffected.
---@field modifyAccountsDisabled? boolean Whether adding or removing accounts is disabled.
---@field usbFileTransferDisabled? boolean Whether transferring files over USB is disabled. This is supported only on company-owned devices.
---@field networkEscapeHatchEnabled? boolean Whether the network escape hatch is enabled. If a network connection can't be made at boot time, the escape hatch prompts the user to temporarily connect to a network in order to refresh the device policy. After applying policy, the temporary network will be forgotten and the device will continue booting. This prevents being unable to connect to a network if there is no suitable network in the last policy and the device boots into an app in lock task mode, or the user is otherwise unable to reach device settings.Note: Setting wifiConfigDisabled to true will override this setting under specific circumstances. Please see wifiConfigDisabled for further details. Setting configureWifi to DISALLOW_CONFIGURING_WIFI will override this setting under specific circumstances. Please see DISALLOW_CONFIGURING_WIFI for further details.
---@field createWindowsDisabled? boolean Whether creating windows besides app windows is disabled.
---@field complianceRules? gcp.androidmanagement_v1.ComplianceRuleList Rules declaring which mitigating actions to take when a device is not compliant with its policy. When the conditions for multiple rules are satisfied, all of the mitigating actions for the rules are taken. There is a maximum limit of 100 rules. Use policy enforcement rules instead.
---@field ensureVerifyAppsEnabled? boolean Whether app verification is force-enabled.
---@field advancedSecurityOverrides? gcp.androidmanagement_v1.AdvancedSecurityOverrides Optional. Advanced security settings. In most cases, setting these is not needed.
---@field permittedAccessibilityServices? gcp.androidmanagement_v1.PackageNameList Specifies permitted accessibility services. If the field is not set, any accessibility service can be used. If the field is set, only the accessibility services in this list and the system's built-in accessibility service can be used. In particular, if the field is set to empty, only the system's built-in accessibility servicess can be used. This can be set on fully managed devices and on work profiles. When applied to a work profile, this affects both the personal profile and the work profile.
---@field crossDevicePolicies? gcp.androidmanagement_v1.CrossDevicePolicies Optional. Policies controlling cross-device communication.
---@field systemUpdate? gcp.androidmanagement_v1.SystemUpdate The system update policy, which controls how OS updates are applied. If the update type is WINDOWED, the update window will automatically apply to Play app updates as well.Note: Google Play system updates (https://source.android.com/docs/core/ota/modular-system) (also called Mainline updates) are automatically downloaded and require a device reboot to be installed. Refer to the mainline section in Manage system updates (https://developer.android.com/work/dpc/system-updates#mainline) for further details.If this policy is set, it takes precedence over unifiedUpdatePolicy for OEM OS updates. For more information, see unifiedUpdatePolicy.
---@field funDisabled? boolean Whether the user is allowed to have fun. Controls whether the Easter egg game in Settings is disabled.
---@field mountPhysicalMediaDisabled? boolean Whether the user mounting physical external media is disabled.
---@field unifiedUpdatePolicy? gcp.androidmanagement_v1.UnifiedUpdatePolicy Optional. The Unified Update Control policy, for controlling updates of software components on the device. Supported only on company-owned devices.The targets OS_UPDATE_WITH_API_LEVEL_CHANGE and OS_UPDATE_WITHOUT_API_LEVEL_CHANGE are supported only on devices where the OEM has integrated with Unified Update Controls, and are ignored otherwise. If systemUpdate is set, then that policy takes precedence and the targets OS_UPDATE_WITH_API_LEVEL_CHANGE and OS_UPDATE_WITHOUT_API_LEVEL_CHANGE are ignored here.
---@field permissionGrants? gcp.androidmanagement_v1.PermissionGrantList Explicit permission or group grants or denials for all apps. These values override the default_permission_policy.
---@field recommendedGlobalProxy? gcp.androidmanagement_v1.ProxyInfo The network-independent global HTTP proxy. Typically proxies should be configured per-network in open_network_configuration. However for unusual configurations like general internal filtering a global HTTP proxy may be useful. If the proxy is not accessible, network access may break. The global proxy is only a recommendation and some apps may ignore it.
---@field installAppsDisabled? boolean Whether user installation of apps is disabled.
---@field shareLocationDisabled? boolean Whether location sharing is disabled.
---@field deviceConnectivityManagement? gcp.androidmanagement_v1.DeviceConnectivityManagement Optional. Covers controls for device connectivity such as Wi-Fi, USB data access, keyboard/mouse connections, and more.
---@field keyguardDisabled? boolean If true, this disables the Lock Screen (https://source.android.com/docs/core/display/multi_display/lock-screen) for primary and/or secondary displays. This policy is supported only in dedicated device management mode.
---@field printingPolicy? gcp.androidmanagement_v1.PolicyPrintingPolicyEnum|string Optional. Controls whether printing is allowed. This is supported on devices running Android 9 and above. .
---@field minimumApiLevel? number The minimum allowed Android API level. A NonComplianceDetail with OS_NOT_PERMITTED is reported if the Android API level of the device is lower than this value.
---@field blockApplicationsEnabled? boolean This field has no effect.
---@field permittedInputMethods? gcp.androidmanagement_v1.PackageNameList If present, only the input methods provided by packages in this list are permitted. If this field is present, but the list is empty, then only system input methods are permitted.
---@field outgoingCallsDisabled? boolean Whether outgoing calls are disabled.
---@field openNetworkConfiguration? gcp.androidmanagement_v1.DocumentMap Network configuration for the device. See configure networks for more information.
---@field name string The name of the policy in the form enterprises/{enterpriseId}/policies/{policyId}.
---@field updateMask? string The field mask indicating the fields to update. If not set, all modifiable fields will be modified.

---@class gcp.androidmanagement_v1.PatchEnterprisesRequest
---@field logo? gcp.androidmanagement_v1.ExternalData An image displayed as a logo during device provisioning. Supported types are: image/bmp, image/gif, image/x-ico, image/jpeg, image/png, image/webp, image/vnd.wap.wbmp, image/x-adobe-dng.
---@field signinDetails? gcp.androidmanagement_v1.SigninDetailList Sign-in details of the enterprise.
---@field primaryColor? number A color in RGB format that indicates the predominant color to display in the device management app UI. The color components are stored as follows: (red << 16) | (green << 8) | blue, where the value of each component is between 0 and 255, inclusive.
---@field managedGoogleDomainType? gcp.androidmanagement_v1.EnterpriseManagedGoogleDomainTypeEnum|string Output only. The type of managed Google domain.
---@field enabledNotificationTypes? gcp.androidmanagement_v1.EnterpriseEnabledNotificationTypesItemEnumList The types of Google Pub/Sub notifications enabled for the enterprise.
---@field enterpriseType? gcp.androidmanagement_v1.EnterpriseEnterpriseTypeEnum|string Output only. The type of the enterprise.
---@field contactInfo? gcp.androidmanagement_v1.ContactInfo The enterprise contact info of an EMM-managed enterprise.
---@field pubsubTopic? string The topic which Pub/Sub notifications are published to, in the form projects/{project}/topics/{topic}. This field is only required if Pub/Sub notifications are enabled.
---@field appAutoApprovalEnabled? boolean Deprecated and unused.
---@field managedGooglePlayAccountsEnterpriseType? gcp.androidmanagement_v1.EnterpriseManagedGooglePlayAccountsEnterpriseTypeEnum|string Output only. The type of a managed Google Play Accounts enterprise.
---@field enterpriseDisplayName? string The name of the enterprise displayed to users. This field has a maximum length of 100 characters.
---@field termsAndConditions? gcp.androidmanagement_v1.TermsAndConditionsList Terms and conditions that must be accepted when provisioning a device for this enterprise. A page of terms is generated for each value in this list.
---@field googleAuthenticationSettings? gcp.androidmanagement_v1.GoogleAuthenticationSettings Settings for Google-provided user authentication.
---@field name string The name of the enterprise in the form enterprises/{enterpriseId}.
---@field updateMask? string The field mask indicating the fields to update. If not set, all modifiable fields will be modified.

---@class gcp.androidmanagement_v1.PatchEnterprisesWebAppsRequest
---@field title? string The title of the web app as displayed to the user (e.g., amongst a list of other applications, or as a label for an icon).
---@field icons? gcp.androidmanagement_v1.WebAppIconList A list of icons for the web app. Must have at least one element.
---@field displayMode? gcp.androidmanagement_v1.WebAppDisplayModeEnum|string The display mode of the web app.
---@field versionCode? string The current version of the app.Note that the version can automatically increase during the lifetime of the web app, while Google does internal housekeeping to keep the web app up-to-date.
---@field startUrl? string The start URL, i.e. the URL that should load when the user opens the application.
---@field name string The name of the web app in the form enterprises/{enterpriseId}/webApps/{packageName}.
---@field updateMask? string The field mask indicating the fields to update. If not set, all modifiable fields will be modified.

---The result of an attempt to clear the data of a single app.
---@class gcp.androidmanagement_v1.PerAppResult
---@field clearingResult? gcp.androidmanagement_v1.PerAppResultClearingResultEnum|string The result of an attempt to clear the data of a single app.

---@alias gcp.androidmanagement_v1.PerAppResultClearingResultEnum "CLEARING_RESULT_UNSPECIFIED"|"SUCCESS"|"APP_NOT_FOUND"|"APP_PROTECTED"|"API_LEVEL"

---@alias gcp.androidmanagement_v1.PerAppResultMap { [string]: gcp.androidmanagement_v1.PerAppResult }

---Configuration for an Android permission and its grant state.
---@class gcp.androidmanagement_v1.PermissionGrant
---@field permission? string The Android permission or group, e.g. android.permission.READ_CALENDAR or android.permission_group.CALENDAR.
---@field policy? gcp.androidmanagement_v1.PermissionGrantPolicyEnum|string The policy for granting the permission.

---@alias gcp.androidmanagement_v1.PermissionGrantList gcp.androidmanagement_v1.PermissionGrant[]

---@alias gcp.androidmanagement_v1.PermissionGrantPolicyEnum "PERMISSION_POLICY_UNSPECIFIED"|"PROMPT"|"GRANT"|"DENY"

---A default activity for handling intents that match a particular intent filter. Note: To set up a kiosk, use InstallType to KIOSK rather than use persistent preferred activities.
---@class gcp.androidmanagement_v1.PersistentPreferredActivity
---@field categories? gcp.androidmanagement_v1.StringList The intent categories to match in the filter. An intent includes the categories that it requires, all of which must be included in the filter in order to match. In other words, adding a category to the filter has no impact on matching unless that category is specified in the intent.
---@field actions? gcp.androidmanagement_v1.StringList The intent actions to match in the filter. If any actions are included in the filter, then an intent's action must be one of those values for it to match. If no actions are included, the intent action is ignored.
---@field receiverActivity? string The activity that should be the default intent handler. This should be an Android component name, e.g. com.android.enterprise.app/.MainActivity. Alternatively, the value may be the package name of an app, which causes Android Device Policy to choose an appropriate activity from the app to handle the intent.

---@alias gcp.androidmanagement_v1.PersistentPreferredActivityList gcp.androidmanagement_v1.PersistentPreferredActivity[]

---Policies for apps in the personal profile of a company-owned device with a work profile.
---@class gcp.androidmanagement_v1.PersonalApplicationPolicy
---@field packageName? string The package name of the application.
---@field installType? gcp.androidmanagement_v1.PersonalApplicationPolicyInstallTypeEnum|string The type of installation to perform.

---@alias gcp.androidmanagement_v1.PersonalApplicationPolicyInstallTypeEnum "INSTALL_TYPE_UNSPECIFIED"|"BLOCKED"|"AVAILABLE"

---@alias gcp.androidmanagement_v1.PersonalApplicationPolicyList gcp.androidmanagement_v1.PersonalApplicationPolicy[]

---Policies controlling cross-device communication in the personal profile.
---@class gcp.androidmanagement_v1.PersonalCrossDevicePolicies
---@field taskContinuityHandoff? gcp.androidmanagement_v1.PersonalCrossDevicePoliciesTaskContinuityHandoffEnum|string Optional. Controls the task continuity handoff (https://developer.android.com/partners/android-17/features#handoff) feature for the personal profile on company-owned devices with a work profile. To disable Handoff device-wide on a company-owned device, both crossDevicePolicies.taskContinuityHandoff and this policy should be set to TASK_CONTINUITY_HANDOFF_DISALLOWED. Requires Android 17 QPR1 or higher.

---@alias gcp.androidmanagement_v1.PersonalCrossDevicePoliciesTaskContinuityHandoffEnum "TASK_CONTINUITY_HANDOFF_UNSPECIFIED"|"TASK_CONTINUITY_HANDOFF_ALLOWED"|"TASK_CONTINUITY_HANDOFF_DISALLOWED"

---Policies controlling personal usage on a company-owned device with a work profile.
---@class gcp.androidmanagement_v1.PersonalUsagePolicies
---@field maxDaysWithWorkOff? number Controls how long the work profile can stay off. The minimum duration must be at least 3 days. Other details are as follows: - If the duration is set to 0, the feature is turned off. - If the duration is set to a value smaller than the minimum duration, the feature returns an error. *Note:* If you want to avoid personal profiles being suspended during long periods of off-time, you can temporarily set a large value for this parameter.
---@field screenCaptureDisabled? boolean If true, screen capture is disabled for all users. This also blocks Circle to Search (https://support.google.com/android/answer/14508957).
---@field cameraDisabled? boolean If true, the camera is disabled on the personal profile.
---@field personalApplications? gcp.androidmanagement_v1.PersonalApplicationPolicyList Policy applied to applications in the personal profile.
---@field crossDevicePolicies? gcp.androidmanagement_v1.PersonalCrossDevicePolicies Optional. Policies controlling cross-device communication in the personal profile.
---@field accountTypesWithManagementDisabled? gcp.androidmanagement_v1.StringList Account types that can't be managed by the user.
---@field privateSpacePolicy? gcp.androidmanagement_v1.PersonalUsagePoliciesPrivateSpacePolicyEnum|string Optional. Controls whether a private space is allowed on the device.
---@field personalPlayStoreMode? gcp.androidmanagement_v1.PersonalUsagePoliciesPersonalPlayStoreModeEnum|string Used together with personalApplications to control how apps in the personal profile are allowed or blocked.
---@field bluetoothSharing? gcp.androidmanagement_v1.PersonalUsagePoliciesBluetoothSharingEnum|string Optional. Whether bluetooth sharing is allowed.

---@alias gcp.androidmanagement_v1.PersonalUsagePoliciesBluetoothSharingEnum "BLUETOOTH_SHARING_UNSPECIFIED"|"BLUETOOTH_SHARING_ALLOWED"|"BLUETOOTH_SHARING_DISALLOWED"

---@alias gcp.androidmanagement_v1.PersonalUsagePoliciesPersonalPlayStoreModeEnum "PLAY_STORE_MODE_UNSPECIFIED"|"BLACKLIST"|"BLOCKLIST"|"ALLOWLIST"

---@alias gcp.androidmanagement_v1.PersonalUsagePoliciesPrivateSpacePolicyEnum "PRIVATE_SPACE_POLICY_UNSPECIFIED"|"PRIVATE_SPACE_ALLOWED"|"PRIVATE_SPACE_DISALLOWED"

---A policy resource represents a group of settings that govern the behavior of a managed device and the apps installed on it.
---@class gcp.androidmanagement_v1.Policy
---@field statusBarDisabled? boolean Whether the status bar is disabled. This disables notifications, quick settings, and other screen overlays that allow escape from full-screen mode. DEPRECATED. To disable the status bar on a kiosk device, use InstallType KIOSK or kioskCustomLauncherEnabled.
---@field personalUsagePolicies? gcp.androidmanagement_v1.PersonalUsagePolicies Policies managing personal usage on a company-owned device.
---@field passwordPolicies? gcp.androidmanagement_v1.PasswordRequirementsList Optional. Password requirement policies. Different policies can be set for work profile or fully managed devices by setting the password_scope field in the policy.
---@field smsDisabled? boolean Whether sending and receiving SMS messages is disabled.
---@field backupService? gcp.androidmanagement_v1.PolicyBackupServiceEnum Optional. Controls whether the backup service is disabled. Supported only on fully managed devices running Android 8 and above.
---@field cameraAccess? gcp.androidmanagement_v1.PolicyCameraAccessEnum Controls the use of the camera and whether the user has access to the camera access toggle.
---@field deviceWidePolicies? gcp.androidmanagement_v1.DeviceWidePolicies Optional. Policies controlling the device on company-owned devices.
---@field statusReportingSettings? gcp.androidmanagement_v1.StatusReportingSettings Status reporting settings
---@field addUserDisabled? boolean Whether adding new users and profiles is disabled. For devices where managementMode is DEVICE_OWNER this field is ignored and the user is never allowed to add or remove users.
---@field encryptionPolicy? gcp.androidmanagement_v1.PolicyEncryptionPolicyEnum Whether encryption is enabled
---@field policyEnforcementRules? gcp.androidmanagement_v1.PolicyEnforcementRuleList Rules that define the behavior when a particular policy can not be applied on device
---@field appFunctions? gcp.androidmanagement_v1.PolicyAppFunctionsEnum Optional. Controls whether apps on the device for fully managed devices or in the work profile for devices with work profiles are allowed to expose app functions.
---@field locationMode? gcp.androidmanagement_v1.PolicyLocationModeEnum The degree of location detection enabled.
---@field defaultPermissionPolicy? gcp.androidmanagement_v1.PolicyDefaultPermissionPolicyEnum The default permission policy for runtime permission requests.
---@field androidDevicePolicyTracks? gcp.androidmanagement_v1.PolicyAndroidDevicePolicyTracksItemEnumList This setting is not supported. Any value is ignored.
---@field unmuteMicrophoneDisabled? boolean If microphone_access is set to any value other than MICROPHONE_ACCESS_UNSPECIFIED, this has no effect. Otherwise this field controls whether microphones are disabled: If true, all microphones are disabled, otherwise they are available. This is available only on fully managed devices.
---@field microphoneAccess? gcp.androidmanagement_v1.PolicyMicrophoneAccessEnum Controls the use of the microphone and whether the user has access to the microphone access toggle. This applies only on fully managed devices.
---@field installUnknownSourcesAllowed? boolean This field has no effect.
---@field kioskCustomLauncherEnabled? boolean Whether the kiosk custom launcher is enabled. This replaces the home screen with a launcher that locks down the device to the apps installed via the applications setting. Apps appear on a single page in alphabetical order. Use kioskCustomization to further configure the kiosk device behavior.
---@field usbMassStorageEnabled? boolean Whether USB storage is enabled. Deprecated.
---@field deviceRadioState? gcp.androidmanagement_v1.DeviceRadioState Optional. Covers controls for radio state such as Wi-Fi, bluetooth, and more.
---@field networkResetDisabled? boolean Whether resetting network settings is disabled. This applies only on fully managed devices. A NonComplianceDetail with MANAGEMENT_MODE is reported for other management modes.
---@field wipeDataFlags? gcp.androidmanagement_v1.PolicyWipeDataFlagsItemEnumList Optional. Wipe flags to indicate what data is wiped when a device or profile wipe is triggered due to any reason (for example, non-compliance). This does not apply to the enterprises.devices.delete method. . This list must not have duplicates.
---@field defaultApplicationSettings? gcp.androidmanagement_v1.DefaultApplicationSettingList Optional. The default application setting for supported types. If the default application is successfully set for at least one app type on a profile, users are prevented from changing any default applications on that profile.Only one DefaultApplicationSetting is allowed for each DefaultApplicationType.Warning: Do not configure this and persistent_preferred_activities for the same intent domain, such as web browsing. Setting both for the same intent domain can lead to unpredictable behavior.See Default application settings (https://developers.google.com/android/management/default-application-settings) guide for more details.
---@field factoryResetDisabled? boolean Whether factory resetting from settings is disabled.
---@field privateKeySelectionEnabled? boolean Allows showing UI on a device for a user to choose a private key alias if there are no matching rules in ChoosePrivateKeyRules. For devices below Android P, setting this may leave enterprise keys vulnerable. This value will have no effect if any application has CERT_SELECTION delegation scope.
---@field dataRoamingDisabled? boolean Whether roaming data services are disabled.
---@field wifiConfigsLockdownEnabled? boolean This is deprecated.
---@field longSupportMessage? gcp.androidmanagement_v1.UserFacingMessage A message displayed to the user in the device administators settings screen.
---@field bluetoothContactSharingDisabled? boolean Whether bluetooth contact sharing is disabled.
---@field debuggingFeaturesAllowed? boolean Whether the user is allowed to enable debugging features.
---@field adjustVolumeDisabled? boolean Whether adjusting the master volume is disabled. Also mutes the device. The setting has effect only on fully managed devices.
---@field autofillPolicy? gcp.androidmanagement_v1.PolicyAutofillPolicyEnum Optional. The policy for the autofill service.
---@field mobileNetworksConfigDisabled? boolean Whether configuring mobile networks is disabled.
---@field assistContentPolicy? gcp.androidmanagement_v1.PolicyAssistContentPolicyEnum Optional. Controls whether AssistContent (https://developer.android.com/reference/android/app/assist/AssistContent) is allowed to be sent to a privileged app such as an assistant app. AssistContent includes screenshots and information about an app, such as package name. This is supported on Android 15 and above.
---@field autoTimeRequired? boolean Whether auto time is required, which prevents the user from manually setting the date and time. If autoDateAndTimeZone is set, this field is ignored.
---@field applications? gcp.androidmanagement_v1.ApplicationPolicyList Policy applied to apps. This can have at most 3,000 elements.
---@field setupActions? gcp.androidmanagement_v1.SetupActionList Action to take during the setup process. At most one action may be specified.
---@field autoDateAndTimeZone? gcp.androidmanagement_v1.PolicyAutoDateAndTimeZoneEnum Whether auto date, time, and time zone are enabled on a company-owned device. If this is set, then autoTimeRequired is ignored.
---@field alwaysOnVpnPackage? gcp.androidmanagement_v1.AlwaysOnVpnPackage Configuration for an always-on VPN connection. Use with vpn_config_disabled to prevent modification of this setting.
---@field skipFirstUseHintsEnabled? boolean Flag to skip hints on the first use. Enterprise admin can enable the system recommendation for apps to skip their user tutorial and other introductory hints on first start-up.
---@field usageLog? gcp.androidmanagement_v1.UsageLog Optional. Configuration of device activity logging.
---@field version? string The version of the policy. This is a read-only field. The version is incremented each time the policy is updated.
---@field maximumTimeToLock? string Maximum time in milliseconds for user activity until the device locks. A value of 0 means there is no restriction.
---@field safeBootDisabled? boolean Whether rebooting the device into safe boot is disabled.
---@field credentialsConfigDisabled? boolean Whether configuring user credentials is disabled.
---@field tetheringConfigDisabled? boolean Whether configuring tethering and portable hotspots is disabled. If tetheringSettings is set to anything other than TETHERING_SETTINGS_UNSPECIFIED, this setting is ignored.
---@field oncCertificateProviders? gcp.androidmanagement_v1.OncCertificateProviderList This feature is not generally available.
---@field vpnConfigDisabled? boolean Whether configuring VPN is disabled.
---@field setWallpaperDisabled? boolean Whether changing the wallpaper is disabled.
---@field deviceOwnerLockScreenInfo? gcp.androidmanagement_v1.UserFacingMessage Optional. The device owner information to be shown on the lock screen.
---@field passwordRequirements? gcp.androidmanagement_v1.PasswordRequirements Password requirements. The field password_requirements.require_password_unlock must not be set. DEPRECATED - Use passwordPolicies.Note:Complexity-based values of PasswordQuality, that is, COMPLEXITY_LOW, COMPLEXITY_MEDIUM, and COMPLEXITY_HIGH, cannot be used here. unified_lock_settings cannot be used here.
---@field crossProfilePolicies? gcp.androidmanagement_v1.CrossProfilePolicies Optional. Cross-profile policies applied on the device.
---@field workAccountSetupConfig? gcp.androidmanagement_v1.WorkAccountSetupConfig Optional. Controls the work account setup configuration, such as details of whether a Google authenticated account is required.
---@field accountTypesWithManagementDisabled? gcp.androidmanagement_v1.StringList Account types that can't be managed by the user.
---@field kioskCustomization? gcp.androidmanagement_v1.KioskCustomization Optional. Settings controlling the behavior of a device in kiosk mode. To enable kiosk mode, set kioskCustomLauncherEnabled to true or specify an app in the policy with the KIOSK role.
---@field preferentialNetworkService? gcp.androidmanagement_v1.PolicyPreferentialNetworkServiceEnum Controls whether preferential network service is enabled on the work profile or on fully managed devices. For example, an organization may have an agreement with a carrier that all of the work data from its employees' devices will be sent via a network service dedicated for enterprise use. An example of a supported preferential network service is the enterprise slice on 5G networks. This policy has no effect if preferentialNetworkServiceSettings or ApplicationPolicy.preferentialNetworkId is set on devices running Android 13 or above.
---@field setUserIconDisabled? boolean Whether changing the user icon is disabled. This applies only on devices running Android 7 and above.
---@field stayOnPluggedModes? gcp.androidmanagement_v1.PolicyStayOnPluggedModesItemEnumList The battery plugged in modes for which the device stays on. When using this setting, it is recommended to clear maximum_time_to_lock so that the device doesn't lock itself while it stays on.
---@field bluetoothConfigDisabled? boolean Whether configuring bluetooth is disabled.
---@field displaySettings? gcp.androidmanagement_v1.DisplaySettings Optional. Controls for the display settings.
---@field screenCaptureDisabled? boolean Whether screen capture is disabled. This also blocks Circle to Search (https://support.google.com/android/answer/14508957).
---@field choosePrivateKeyRules? gcp.androidmanagement_v1.ChoosePrivateKeyRuleList Rules for determining apps' access to private keys. See ChoosePrivateKeyRule for details. This must be empty if any application has CERT_SELECTION delegation scope.
---@field removeUserDisabled? boolean Whether removing other users is disabled.
---@field appAutoUpdatePolicy? gcp.androidmanagement_v1.PolicyAppAutoUpdatePolicyEnum Recommended alternative: autoUpdateMode which is set per app, provides greater flexibility around update frequency.When autoUpdateMode is set to AUTO_UPDATE_POSTPONED or AUTO_UPDATE_HIGH_PRIORITY, this field has no effect.The app auto update policy, which controls when automatic app updates can be applied.
---@field shortSupportMessage? gcp.androidmanagement_v1.UserFacingMessage A message displayed to the user in the settings screen wherever functionality has been disabled by the admin. If the message is longer than 200 characters it may be truncated.
---@field cellBroadcastsConfigDisabled? boolean Whether configuring cell broadcast is disabled.
---@field enterpriseDisplayNameVisibility? gcp.androidmanagement_v1.PolicyEnterpriseDisplayNameVisibilityEnum Optional. Controls whether the enterpriseDisplayName is visible on the device (e.g. lock screen message on company-owned devices).
---@field uninstallAppsDisabled? boolean Whether user uninstallation of applications is disabled. This prevents apps from being uninstalled, even those removed using applications
---@field bluetoothDisabled? boolean Whether bluetooth is disabled. Prefer this setting over bluetooth_config_disabled because bluetooth_config_disabled can be bypassed by the user.
---@field playStoreMode? gcp.androidmanagement_v1.PolicyPlayStoreModeEnum This mode controls which apps are available to the user in the Play Store and the behavior on the device when apps are removed from the policy.
---@field credentialProviderPolicyDefault? gcp.androidmanagement_v1.PolicyCredentialProviderPolicyDefaultEnum Optional. Controls which apps are allowed to act as credential providers on Android 14 and above. These apps store credentials, see this (https://developer.android.com/training/sign-in/passkeys) and this (https://developer.android.com/reference/androidx/credentials/CredentialManager) for details. See also credentialProviderPolicy.
---@field outgoingBeamDisabled? boolean Whether using NFC to beam data from apps is disabled.
---@field wifiConfigDisabled? boolean Whether configuring Wi-Fi networks is disabled. Supported on fully managed devices and work profiles on company-owned devices. For fully managed devices, setting this to true removes all configured networks and retains only the networks configured using openNetworkConfiguration. For work profiles on company-owned devices, existing configured networks are not affected and the user is not allowed to add, remove, or modify Wi-Fi networks. If configureWifi is set to anything other than CONFIGURE_WIFI_UNSPECIFIED, this setting is ignored. Note: If a network connection can't be made at boot time and configuring Wi-Fi is disabled then network escape hatch will be shown in order to refresh the device policy (see networkEscapeHatchEnabled).
---@field keyguardDisabledFeatures? gcp.androidmanagement_v1.PolicyKeyguardDisabledFeaturesItemEnumList Disabled keyguard customizations, such as widgets.
---@field persistentPreferredActivities? gcp.androidmanagement_v1.PersistentPreferredActivityList Default intent handler activities.Warning: Do not configure this and default_application_settings for the same intent domain, such as web browsing. Setting both for the same intent domain can lead to unpredictable behavior.
---@field frpAdminEmails? gcp.androidmanagement_v1.StringList Email addresses of device administrators for factory reset protection. When the device is factory reset, it will require one of these admins to log in with the Google account email and password to unlock the device. If no admins are specified, the device won't provide factory reset protection.
---@field cameraDisabled? boolean If camera_access is set to any value other than CAMERA_ACCESS_UNSPECIFIED, this has no effect. Otherwise this field controls whether cameras are disabled: If true, all cameras are disabled, otherwise they are available. For fully managed devices this field applies for all apps on the device. For work profiles, this field applies only to apps in the work profile, and the camera access of apps outside the work profile is unaffected.
---@field modifyAccountsDisabled? boolean Whether adding or removing accounts is disabled.
---@field usbFileTransferDisabled? boolean Whether transferring files over USB is disabled. This is supported only on company-owned devices.
---@field networkEscapeHatchEnabled? boolean Whether the network escape hatch is enabled. If a network connection can't be made at boot time, the escape hatch prompts the user to temporarily connect to a network in order to refresh the device policy. After applying policy, the temporary network will be forgotten and the device will continue booting. This prevents being unable to connect to a network if there is no suitable network in the last policy and the device boots into an app in lock task mode, or the user is otherwise unable to reach device settings.Note: Setting wifiConfigDisabled to true will override this setting under specific circumstances. Please see wifiConfigDisabled for further details. Setting configureWifi to DISALLOW_CONFIGURING_WIFI will override this setting under specific circumstances. Please see DISALLOW_CONFIGURING_WIFI for further details.
---@field createWindowsDisabled? boolean Whether creating windows besides app windows is disabled.
---@field complianceRules? gcp.androidmanagement_v1.ComplianceRuleList Rules declaring which mitigating actions to take when a device is not compliant with its policy. When the conditions for multiple rules are satisfied, all of the mitigating actions for the rules are taken. There is a maximum limit of 100 rules. Use policy enforcement rules instead.
---@field ensureVerifyAppsEnabled? boolean Whether app verification is force-enabled.
---@field advancedSecurityOverrides? gcp.androidmanagement_v1.AdvancedSecurityOverrides Optional. Advanced security settings. In most cases, setting these is not needed.
---@field permittedAccessibilityServices? gcp.androidmanagement_v1.PackageNameList Specifies permitted accessibility services. If the field is not set, any accessibility service can be used. If the field is set, only the accessibility services in this list and the system's built-in accessibility service can be used. In particular, if the field is set to empty, only the system's built-in accessibility servicess can be used. This can be set on fully managed devices and on work profiles. When applied to a work profile, this affects both the personal profile and the work profile.
---@field crossDevicePolicies? gcp.androidmanagement_v1.CrossDevicePolicies Optional. Policies controlling cross-device communication.
---@field systemUpdate? gcp.androidmanagement_v1.SystemUpdate The system update policy, which controls how OS updates are applied. If the update type is WINDOWED, the update window will automatically apply to Play app updates as well.Note: Google Play system updates (https://source.android.com/docs/core/ota/modular-system) (also called Mainline updates) are automatically downloaded and require a device reboot to be installed. Refer to the mainline section in Manage system updates (https://developer.android.com/work/dpc/system-updates#mainline) for further details.If this policy is set, it takes precedence over unifiedUpdatePolicy for OEM OS updates. For more information, see unifiedUpdatePolicy.
---@field funDisabled? boolean Whether the user is allowed to have fun. Controls whether the Easter egg game in Settings is disabled.
---@field mountPhysicalMediaDisabled? boolean Whether the user mounting physical external media is disabled.
---@field unifiedUpdatePolicy? gcp.androidmanagement_v1.UnifiedUpdatePolicy Optional. The Unified Update Control policy, for controlling updates of software components on the device. Supported only on company-owned devices.The targets OS_UPDATE_WITH_API_LEVEL_CHANGE and OS_UPDATE_WITHOUT_API_LEVEL_CHANGE are supported only on devices where the OEM has integrated with Unified Update Controls, and are ignored otherwise. If systemUpdate is set, then that policy takes precedence and the targets OS_UPDATE_WITH_API_LEVEL_CHANGE and OS_UPDATE_WITHOUT_API_LEVEL_CHANGE are ignored here.
---@field permissionGrants? gcp.androidmanagement_v1.PermissionGrantList Explicit permission or group grants or denials for all apps. These values override the default_permission_policy.
---@field recommendedGlobalProxy? gcp.androidmanagement_v1.ProxyInfo The network-independent global HTTP proxy. Typically proxies should be configured per-network in open_network_configuration. However for unusual configurations like general internal filtering a global HTTP proxy may be useful. If the proxy is not accessible, network access may break. The global proxy is only a recommendation and some apps may ignore it.
---@field name? string The name of the policy in the form enterprises/{enterpriseId}/policies/{policyId}.
---@field installAppsDisabled? boolean Whether user installation of apps is disabled.
---@field shareLocationDisabled? boolean Whether location sharing is disabled.
---@field deviceConnectivityManagement? gcp.androidmanagement_v1.DeviceConnectivityManagement Optional. Covers controls for device connectivity such as Wi-Fi, USB data access, keyboard/mouse connections, and more.
---@field keyguardDisabled? boolean If true, this disables the Lock Screen (https://source.android.com/docs/core/display/multi_display/lock-screen) for primary and/or secondary displays. This policy is supported only in dedicated device management mode.
---@field printingPolicy? gcp.androidmanagement_v1.PolicyPrintingPolicyEnum Optional. Controls whether printing is allowed. This is supported on devices running Android 9 and above. .
---@field minimumApiLevel? number The minimum allowed Android API level. A NonComplianceDetail with OS_NOT_PERMITTED is reported if the Android API level of the device is lower than this value.
---@field blockApplicationsEnabled? boolean This field has no effect.
---@field permittedInputMethods? gcp.androidmanagement_v1.PackageNameList If present, only the input methods provided by packages in this list are permitted. If this field is present, but the list is empty, then only system input methods are permitted.
---@field outgoingCallsDisabled? boolean Whether outgoing calls are disabled.
---@field openNetworkConfiguration? gcp.androidmanagement_v1.DocumentMap Network configuration for the device. See configure networks for more information.

---@alias gcp.androidmanagement_v1.PolicyAndroidDevicePolicyTracksItemEnum "APP_TRACK_UNSPECIFIED"|"PRODUCTION"|"BETA"

---@alias gcp.androidmanagement_v1.PolicyAndroidDevicePolicyTracksItemEnumList (gcp.androidmanagement_v1.PolicyAndroidDevicePolicyTracksItemEnum|string)[]

---@alias gcp.androidmanagement_v1.PolicyAppAutoUpdatePolicyEnum "APP_AUTO_UPDATE_POLICY_UNSPECIFIED"|"CHOICE_TO_THE_USER"|"NEVER"|"WIFI_ONLY"|"ALWAYS"

---@alias gcp.androidmanagement_v1.PolicyAppFunctionsEnum "APP_FUNCTIONS_UNSPECIFIED"|"APP_FUNCTIONS_DISALLOWED"|"APP_FUNCTIONS_ALLOWED"

---@alias gcp.androidmanagement_v1.PolicyAssistContentPolicyEnum "ASSIST_CONTENT_POLICY_UNSPECIFIED"|"ASSIST_CONTENT_DISALLOWED"|"ASSIST_CONTENT_ALLOWED"

---@alias gcp.androidmanagement_v1.PolicyAutoDateAndTimeZoneEnum "AUTO_DATE_AND_TIME_ZONE_UNSPECIFIED"|"AUTO_DATE_AND_TIME_ZONE_USER_CHOICE"|"AUTO_DATE_AND_TIME_ZONE_ENFORCED"

---@alias gcp.androidmanagement_v1.PolicyAutofillPolicyEnum "AUTOFILL_POLICY_UNSPECIFIED"|"AUTOFILL_USER_CHOICE"|"AUTOFILL_DISABLED"

---@alias gcp.androidmanagement_v1.PolicyBackupServiceEnum "BACKUP_SERVICE_UNSPECIFIED"|"BACKUP_SERVICE_DISABLED"|"BACKUP_SERVICE_USER_CHOICE"

---@alias gcp.androidmanagement_v1.PolicyCameraAccessEnum "CAMERA_ACCESS_UNSPECIFIED"|"CAMERA_ACCESS_USER_CHOICE"|"CAMERA_ACCESS_DISABLED"|"CAMERA_ACCESS_ENFORCED"

---@alias gcp.androidmanagement_v1.PolicyCredentialProviderPolicyDefaultEnum "CREDENTIAL_PROVIDER_POLICY_DEFAULT_UNSPECIFIED"|"CREDENTIAL_PROVIDER_DEFAULT_DISALLOWED"|"CREDENTIAL_PROVIDER_DEFAULT_DISALLOWED_EXCEPT_SYSTEM"|"CREDENTIAL_PROVIDER_DEFAULT_ALLOWED"

---@alias gcp.androidmanagement_v1.PolicyDefaultPermissionPolicyEnum "PERMISSION_POLICY_UNSPECIFIED"|"PROMPT"|"GRANT"|"DENY"

---@alias gcp.androidmanagement_v1.PolicyEncryptionPolicyEnum "ENCRYPTION_POLICY_UNSPECIFIED"|"ENABLED_WITHOUT_PASSWORD"|"ENABLED_WITH_PASSWORD"

---A rule that defines the actions to take if a device or work profile is not compliant with the policy specified in settingName. In the case of multiple matching or multiple triggered enforcement rules, a merge will occur with the most severe action being taken. However, all triggered rules are still kept track of: this includes initial trigger time and all associated non-compliance details. In the situation where the most severe enforcement rule is satisfied, the next most appropriate action is applied.
---@class gcp.androidmanagement_v1.PolicyEnforcementRule
---@field settingName? string The top-level policy to enforce. For example, applications or passwordPolicies.
---@field blockAction? gcp.androidmanagement_v1.BlockAction An action to block access to apps and data on a company owned device or in a work profile. This action also triggers a user-facing notification with information (where possible) on how to correct the compliance issue. Note: wipeAction must also be specified.
---@field wipeAction? gcp.androidmanagement_v1.WipeAction An action to reset a company owned device or delete a work profile. Note: blockAction must also be specified.

---@alias gcp.androidmanagement_v1.PolicyEnforcementRuleList gcp.androidmanagement_v1.PolicyEnforcementRule[]

---@alias gcp.androidmanagement_v1.PolicyEnterpriseDisplayNameVisibilityEnum "ENTERPRISE_DISPLAY_NAME_VISIBILITY_UNSPECIFIED"|"ENTERPRISE_DISPLAY_NAME_VISIBLE"|"ENTERPRISE_DISPLAY_NAME_HIDDEN"

---@alias gcp.androidmanagement_v1.PolicyKeyguardDisabledFeaturesItemEnum "KEYGUARD_DISABLED_FEATURE_UNSPECIFIED"|"CAMERA"|"NOTIFICATIONS"|"UNREDACTED_NOTIFICATIONS"|"TRUST_AGENTS"|"DISABLE_FINGERPRINT"|"DISABLE_REMOTE_INPUT"|"FACE"|"IRIS"|"BIOMETRICS"|"SHORTCUTS"|"ALL_FEATURES"

---@alias gcp.androidmanagement_v1.PolicyKeyguardDisabledFeaturesItemEnumList (gcp.androidmanagement_v1.PolicyKeyguardDisabledFeaturesItemEnum|string)[]

---@alias gcp.androidmanagement_v1.PolicyList gcp.androidmanagement_v1.Policy[]

---@alias gcp.androidmanagement_v1.PolicyLocationModeEnum "LOCATION_MODE_UNSPECIFIED"|"HIGH_ACCURACY"|"SENSORS_ONLY"|"BATTERY_SAVING"|"OFF"|"LOCATION_USER_CHOICE"|"LOCATION_ENFORCED"|"LOCATION_DISABLED"

---@alias gcp.androidmanagement_v1.PolicyMicrophoneAccessEnum "MICROPHONE_ACCESS_UNSPECIFIED"|"MICROPHONE_ACCESS_USER_CHOICE"|"MICROPHONE_ACCESS_DISABLED"|"MICROPHONE_ACCESS_ENFORCED"

---@alias gcp.androidmanagement_v1.PolicyPlayStoreModeEnum "PLAY_STORE_MODE_UNSPECIFIED"|"WHITELIST"|"BLACKLIST"

---@alias gcp.androidmanagement_v1.PolicyPreferentialNetworkServiceEnum "PREFERENTIAL_NETWORK_SERVICE_UNSPECIFIED"|"PREFERENTIAL_NETWORK_SERVICE_DISABLED"|"PREFERENTIAL_NETWORK_SERVICE_ENABLED"

---@alias gcp.androidmanagement_v1.PolicyPrintingPolicyEnum "PRINTING_POLICY_UNSPECIFIED"|"PRINTING_DISALLOWED"|"PRINTING_ALLOWED"

---@alias gcp.androidmanagement_v1.PolicyStayOnPluggedModesItemEnum "BATTERY_PLUGGED_MODE_UNSPECIFIED"|"AC"|"USB"|"WIRELESS"

---@alias gcp.androidmanagement_v1.PolicyStayOnPluggedModesItemEnumList (gcp.androidmanagement_v1.PolicyStayOnPluggedModesItemEnum|string)[]

---@alias gcp.androidmanagement_v1.PolicyWipeDataFlagsItemEnum "WIPE_DATA_FLAG_UNSPECIFIED"|"WIPE_ESIMS"

