---@alias gcp.androidmanagement_v1.ScreenTimeoutSettingsScreenTimeoutModeEnum "SCREEN_TIMEOUT_MODE_UNSPECIFIED"|"SCREEN_TIMEOUT_USER_CHOICE"|"SCREEN_TIMEOUT_ENFORCED"

